import{_ as b,z as f,r as v,c as _,o as m,a as p,b as o,e as n,q as a,h as s,p as w,F as y,g as h,k as i,t as k}from"./DHIVwR32.js";const x={class:"back-country"},M={class:"header-content"},T={key:0},I={class:"info"},L={class:"info-loyar"},g={class:"loyar-header"},H=["innerHTML"],W=["innerHTML"],B=Object.assign({name:"loyarInformation"},{__name:"loyarInformation",setup(N){const d=f(),u=[{id:1,header:"Согласие на обработку и использование персональных данных",text:`Настоящим я, являясь Заказчиком туристских услуг, входящих в состав туристского продукта, и уполномоченным представителем лиц (туристов), указанных в договоре и приложениях к нему, даю согласие Агенту и его уполномоченным представителям на обработку моих данных и данных лиц (туристов), содержащихся в Заявке: фамилия, имя, отчество, дата и место рождения, пол, гражданство, серия, номер паспорта, иные данные, указанные в паспорте; адрес проживания и регистрации; домашний и мобильный телефон; адрес электронной почты; а также любых иных данных, относящихся к моей личности и личности лиц, указанных в Заявке, в объёме необходимом для реализации и предоставления туристских услуг, в том числе входящих в состав туристского продукта, сформированного Туроператором, на любое действие (операцию) или совокупность действий (операций), совершаемых с моими персональными данными и данными лиц, указанных в Заявке, включая (без ограничений) сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, обезличивание, блокирование, удаление, уничтожение персональных данных, а также осуществление любых других действий, предусмотренных действующим законодательством Российской Федерации, с использованием средств автоматизации, в том числе в информационно-телекоммуникационных сетях, или без использования таких средств, если обработка персональных данных без использования таких средств соответствует характеру действий (операций), совершаемых с персональными данными с использованием средств автоматизации, то есть позволяет осуществлять в соответствии с заданным алгоритмом поиск персональных данных, зафиксированных на материальном носителе и содержащихся в картотеках или иных систематизированных собраниях персональных данных, и/или доступ к таким персональным данным.
<br/>Обработка персональных данных осуществляется Агентом, Туроператором и непосредственными исполнителями услуг в целях заключения и исполнения настоящего договора (в том числе, в зависимости от условий договора – в целях оформления проездных документов, бронирования номеров в средствах размещения и у перевозчиков, передачи данных в консульство иностранного государства, разрешения претензионных вопросов при их возникновении, в том числе в случае инициирования судебных процессов, связанных с исполнением настоящего Договора, предоставления информации уполномоченным государственным органам (в том числе по запросу судов и органов внутренних дел)).
<br/>Я даю согласие на передачу сведений, полученных в ходе исполнения настоящего договора, в установленном законом порядке в единую информационную систему электронных путевок.
<br/>Настоящим я подтверждаю, что переданные мной Агенту персональные данные являются достоверными и могут обрабатываться Агентом и его уполномоченными представителями.
<br/>Настоящим я подтверждаю наличие у меня полномочий на предоставление персональных данных лиц, указанных в Заявке, и принимаю на себя обязательство возместить Агенту любые расходы, связанные с отсутствием у меня соответствующих полномочий, в том числе убытки, связанные с санкциями проверяющих органов.
 
<br/><br/>Я согласен (на) с тем, что текст данного мной по собственной воле, в моих интересах и в интересах лиц, указанных в Заявке, согласия на обработку персональных данных хранится в электронном виде в базе данных и/или на бумажном носителе и подтверждает факт согласия на обработку персональных данных в соответствии с вышеизложенными положениями, и беру на себя ответственность за достоверность предоставления персональных данных.
<br/>Настоящее согласие дается на срок действия настоящего договора и продолжает действовать в течение 5 (пять) лет с момента прекращения действия настоящего Договора и может быть в любой момент отозвано мной, а в части, касающейся конкретного лица, субъекта персональных данных, указанного в Заявке, указанным лицом, путем направления письменного заявления в адрес Агента и Туроператора по почте.
<br/>Адрес Агента и Туроператора указан в настоящем договоре и приложениях к нему.
<br/>Настоящим я подтверждаю, что мои права, как субъекта персональных данных, мне разъяснены Агентом и мне понятны.
<br/>Настоящим я подтверждаю, что порядок и последствия отзыва настоящего согласия мне разъяснены Агентом и мне понятны.
 
<br/><br/>Настоящим я даю свое согласие Агенту и Туроператору направлять мне электронные письма/информационные или рекламные сообщения на указанный мной адрес электронной почты и/или номер мобильного телефона, а также даю согласие на обработку своих персональных данных в указанных целях. Данное согласие я даю по своей воле, осознанно и без принуждения.
При заключении договора я проинформирован о своем праве отказаться от получения указанной информации.`},{id:2,header:"Согласие на распространение персональных данных",text:`Настоящим я, являясь Заказчиком туристских услуг, входящих в состав туристского продукта, и уполномоченным представителем лиц (туристов), указанных в договоре и приложениях к нему, даю согласие Агенту на распространение (передачу, предоставление, доступ) моих персональных данных и данных лиц, содержащихся в Заявке, в целях исполнения настоящего договора, а также при размещении моего отзыва на официальном сайте Агента или в социальных сетях Агента. Доступ к моим персональным данным и данным лиц, указанных в Заявке, разрешён неограниченному кругу лиц. Распространяемые данные: фамилия, имя, отчество, город проживания, цветное цифровое фотографическое изображение, контактные данные, а также иные данные, распространение которых необходимо для достижения целей обработки персональных данных. Сведения об информационных ресурсах, посредством которых будут осуществляться предоставление доступа неограниченному кругу лиц и иные действия с персональными данными субъекта персональных данных: сайт Агента и социальные сети Агента. Фамилия имя и отчество, контактная информация субъектов персональных данных, сведения об операторе персональных данных, о его сайте в сети Интернет указаны в договоре.
<br/>В целях исполнения Агентом обязательств, предусмотренных настоящим договором, выражаю согласие на трансграничную передачу моих персональных данных в соответствии с Федеральным законом № 152-ФЗ «О персональных данных» от 27.07.2006 г.
<br/><br/>Перечень персональных данных, на трансграничную передачу которых даётся настоящее согласие:<br/><br/><div style='margin-left: 40px'><ul><li>фамилия, имя, отчество (при наличии) заказчика (туриста) на русском языке</li><li>фамилия, имя в латинской транскрипции, как они указаны в заграничном паспорте</li><li>год, месяц и число рождения</li><li>гражданство в настоящее время (при необходимости – гражданство при рождении)</li><li>пол</li><li>данные о заграничном паспорте РФ (серия и номер заграничного паспорта, дата его выдачи, наименование органа, выдавшего паспорт, срок действия)</li><li>данные свидетельства о рождении (для несовершеннолетних граждан)</li><li>адрес электронной почты</li><li>контактный (мобильный) телефон</li><li>другие персональные данные, необходимые для бронирования и предоставления туристских услуг, входящих в состав туристского продукта</li></ul></div>
<br/><br/>Настоящее согласие дается на срок действия настоящего договора и продолжает действовать в течение 5 (пять) лет с момента прекращения действия настоящего Договора и может быть в любой момент отозвано мной, а в части, касающейся конкретного лица, субъекта персональных данных, указанного в Заявке, указанным лицом, путем направления письменного заявления в адрес Агента и Туроператора по почте`}],r=v(0),l=()=>{typeof window<"u"&&(r.value=window.innerWidth)},c=_(()=>typeof window>"u"?!1:r.value<=576&&r.value>0);return m(()=>{typeof window<"u"&&(r.value=window.innerWidth),l(),typeof window<"u"&&window.addEventListener("resize",l)}),p({title:"Правовая информация | Moov Travel",meta:[{name:"description",content:"Правовая информация и документы туристического агентства Moov Travel."},{name:"robots",content:"noindex, nofollow"}],link:[{rel:"canonical",href:"https://moov-travel.ru/loyarInformation"}]}),(V,e)=>(i(),o("div",null,[n("div",x,[n("div",M,[n("h1",null,[e[1]||(e[1]=a("Правовые")),c.value?(i(),o("br",T)):s("",!0),e[2]||(e[2]=a(" документы"))]),n("button",{class:"back-btn",onClick:e[0]||(e[0]=t=>w(d).back())},"← Назад")])]),n("div",I,[(i(),o(y,null,h(u,t=>n("div",null,[n("div",L,[n("h2",g,k(t.header),1),t.id===1?(i(),o("div",{key:0,class:"loyar-info",innerHTML:t.text},null,8,H)):s("",!0),t.id===2?(i(),o("div",{key:1,class:"loyar-info",innerHTML:t.text},null,8,W)):s("",!0)])])),64))])]))}}),C=b(B,[["__scopeId","data-v-8d7e4bb7"]]);export{C as default};
